package com.yonlab.vision;
import android.content.Context;import android.graphics.*;import android.os.SystemClock;
import org.json.*;import java.io.*;import java.util.*;
/** Actual image inference only. Temporal counting remains in the existing controllers. */
public final class OneModelRunner {
 private OneModelRunner(){}
 public interface Cancel {boolean canceled();}
 public static final class Result {
  public final String feature,modelId;public String state="ERROR",summary="",detail="",errorType="",modelSha256="";
  public long loadMs,inferenceMs,elapsedMs;public boolean engineCreated,engineCloseReturned;public Bitmap image;public JSONObject metrics=new JSONObject();
  Result(String f,String id){feature=f;modelId=id;}
  public void recycle(){if(image!=null&&!image.isRecycled())image.recycle();image=null;}
  public JSONObject json(String inputSha,String demo)throws JSONException{return new JSONObject().put("type","model-image-comparison").put("feature",feature).put("modelId",modelId).put("modelSha256",modelSha256).put("inputSha256",inputSha).put("demoId",demo==null?"":demo).put("state",state).put("createdAt",System.currentTimeMillis()).put("loadMs",loadMs).put("inferenceMs",inferenceMs).put("elapsedMs",elapsedMs).put("summary",summary).put("errorType",errorType).put("metrics",metrics).put("engineCreated",engineCreated).put("engineCloseReturned",engineCloseReturned).put("timingScope","model construction and preprocessing+inference+postprocessing; source decode excluded; SDK lazy initialization may occur in inference");}
 }
 public static Result run(Context c,String feature,String requested,Bitmap input,Cancel cancel){
  String f=OneModelPolicy.canonicalFeature(feature),id=OneModels.resolve(c,f,requested);if(AddedVisionImageRunner.handles(f,id))return AddedVisionImageRunner.run(c,f,id,input,cancel);if("qr".equals(f)&&ModelPlusPolicy.addedQr(id))return AddedQrRunner.run(c,id,input,cancel);if(ExpansionImageRunner.supports(f))return ExpansionImageRunner.run(c,f,id,input,cancel);if(SupplementalImageRunner.supports(f,id))return SupplementalImageRunner.run(c,f,id,input,cancel);Result out=new Result(f,id);long started=SystemClock.elapsedRealtime();AutoCloseable engine=null;
  try{check(cancel);out.image=input.copy(Bitmap.Config.ARGB_8888,true);if(out.image==null)throw new IOException("이미지 준비 실패");Canvas canvas=new Canvas(out.image);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setStrokeWidth(Math.max(2,input.getWidth()/300f));long load=SystemClock.elapsedRealtime();
   if("detect".equals(f)||"flow".equals(f)){
    OneObjectEngine model=new OneObjectEngine(c,id);engine=model;out.modelSha256="yolox-nano".equals(id)?OneYoloXEngine.SHA256:"yolo26n".equals(id)?OneOnnx.expected(id):assetSha(c,"efficientdet-lite0".equals(id)?"models/ball-efficientdet.tflite":"models/detect.tflite");out.loadMs=SystemClock.elapsedRealtime()-load;long infer=SystemClock.elapsedRealtime();List<Observations.Detection> found=model.analyze(input,.4f);check(cancel);out.inferenceMs=SystemClock.elapsedRealtime()-infer;
    JSONArray detections=new JSONArray();for(Observations.Detection d:found){String displayed=OneScoreLabels.detection(d.label,d.score);box(canvas,paint,input,d.left,d.top,d.right,d.bottom,displayed,0xff0068f8);detections.put(new JSONObject().put("label",d.label).put("score",d.score).put("renderedLabel",displayed).put("left",d.left).put("top",d.top).put("right",d.right).put("bottom",d.bottom));}out.metrics.put("detections",detections);out.summary="객체 "+found.size()+"개";if("flow".equals(f))out.detail="사진의 person 검출 비교입니다. 이동 집계는 영상/카메라에서 실행하세요.";
   }else if("classify".equals(f)){
    OneOnnx model=new OneOnnx(c,id);engine=model;out.modelSha256=model.sha256;List<String> labels=new ArrayList<>();OneObjectEngine.read(c,"one/models/imagenet-labels.txt",labels);if(labels.size()!=1000)throw new IOException("ImageNet labels");out.loadMs=SystemClock.elapsedRealtime()-load;long infer=SystemClock.elapsedRealtime();float[] probability=model.run(input,r->{Object v=r.get(0).getValue();if(!(v instanceof float[][])||((float[][])v).length!=1||((float[][])v)[0].length!=1000)throw new IOException("classification output");return OneModelMath.softmax(((float[][])v)[0]);});out.inferenceMs=SystemClock.elapsedRealtime()-infer;check(cancel);List<Integer> order=new ArrayList<>();for(int n=0;n<1000;n++)order.add(n);order.sort((a,b)->Float.compare(probability[b],probability[a]));JSONArray top=new JSONArray();StringBuilder detail=new StringBuilder();for(int n=0;n<5;n++){int i=order.get(n);top.put(new JSONObject().put("classId",i).put("label",labels.get(i)).put("score",probability[i]));detail.append(labels.get(i)).append(" · ").append(String.format(Locale.ROOT,"%.1f%%",probability[i]*100)).append('\n');}out.metrics.put("top5",top);out.summary=labels.get(order.get(0));out.detail=detail.toString();
   }else if("segment".equals(f)){
    OneOnnx model=new OneOnnx(c,id);engine=model;out.modelSha256=model.sha256;out.loadMs=SystemClock.elapsedRealtime()-load;long infer=SystemClock.elapsedRealtime();
    if("pphumanseg-2023".equals(id)){float[][][] scores=model.run(input,r->{Object v=OneOnnx.value(r,"save_infer_model/scale_0.tmp_1");if(!(v instanceof float[][][][]))throw new IOException("PPHumanSeg rank");float[][][][] a=(float[][][][])v;if(a.length!=1||a[0].length!=2||a[0][0].length!=192||a[0][1].length!=192)throw new IOException("PPHumanSeg shape");return a[0];});int w=input.getWidth(),h=input.getHeight();int[] overlay=new int[w*h];long person=0;for(int y=0;y<h;y++){if((y&31)==0)check(cancel);float sy=(y+.5f)*192/h-.5f;for(int x=0;x<w;x++){float sx=(x+.5f)*192/w-.5f;float bg=bilinear(scores[0],sx,sy),fg=bilinear(scores[1],sx,sy);if(fg>bg){overlay[y*w+x]=0x780068f8;person++;}}}Bitmap mask=Bitmap.createBitmap(overlay,w,h,Bitmap.Config.ARGB_8888);canvas.drawBitmap(mask,0,0,null);mask.recycle();out.metrics.put("foregroundPixels",person).put("totalPixels",(long)w*h);out.summary="사람 영역 "+String.format(Locale.ROOT,"%.1f%%",100d*person/(w*h));}
    else{List<String> labels=new ArrayList<>();OneObjectEngine.read(c,"one/models/coco80-labels.txt",labels);int instances=model.run(input,r->{float[][] rows=((float[][][])OneOnnx.value(r,"output0"))[0];float[][][] proto=((float[][][][])OneOnnx.value(r,"output1"))[0];if(rows.length!=300||proto.length!=32||proto[0].length!=160||proto[0][0].length!=160)throw new IOException("YOLO segmentation shape");int kept=0;for(float[] row:rows){check(cancel);if(row.length!=38)throw new IOException("YOLO segmentation width");boolean valid=true;for(float v:row)valid&=OneModelMath.finite(v);if(!valid||row[4]<.4f||row[4]>1||row[5]!=Math.rint(row[5]))continue;int cls=(int)row[5];if(cls<0||cls>=80||row[2]<=row[0]||row[3]<=row[1])continue;float[] b=OneModelMath.unletterbox(row[0],row[1],row[2],row[3],input.getWidth(),input.getHeight(),640);int[] colors=new int[160*160];for(int y=0;y<160;y++)for(int x=0;x<160;x++){if(x*4<row[0]||x*4>=row[2]||y*4<row[1]||y*4>=row[3])continue;float logit=0;for(int k=0;k<32;k++)logit+=row[6+k]*proto[k][y][x];if(OneModelMath.finite(logit)&&logit>0)colors[y*160+x]=0x70000000|(Color.HSVToColor(new float[]{(cls*47)%360,.8f,1})&0xffffff);}Bitmap mask=Bitmap.createBitmap(colors,160,160,Bitmap.Config.ARGB_8888);double scale=Math.min(640d/input.getWidth(),640d/input.getHeight());int rw=(int)Math.round(input.getWidth()*scale),rh=(int)Math.round(input.getHeight()*scale);float left=(640-rw)/2f/4,top=(640-rh)/2f/4;canvas.drawBitmap(mask,new android.graphics.Rect(Math.round(left),Math.round(top),Math.round(left+rw/4f),Math.round(top+rh/4f)),new RectF(0,0,input.getWidth(),input.getHeight()),new Paint(Paint.FILTER_BITMAP_FLAG));mask.recycle();box(canvas,paint,input,b[0],b[1],b[2],b[3],labels.get(cls),0xff0068f8);kept++;if(kept>=12)break;}return kept;});out.metrics.put("instances",instances).put("renderedInstanceLimit",12);out.summary="객체 마스크 "+instances+"개";}
    out.inferenceMs=SystemClock.elapsedRealtime()-infer;
   }else if("ocr".equals(f)||"pose".equals(f)){
    OneTextEngine model="ocr".equals(f)?new OneTextEngine(c,id,cancel):null;OnePoseEngine poseModel="pose".equals(f)?new OnePoseEngine("mlkit-pose-accurate".equals(id)):null;engine=model!=null?model:poseModel;out.loadMs=SystemClock.elapsedRealtime()-load;long infer=SystemClock.elapsedRealtime();if("ocr".equals(f)){out.modelSha256=model.modelSha256;PhotoVisionEngine.Ocr found=model.ocr(input);for(PhotoVisionEngine.TextBox b:found.boxes)box(canvas,paint,input,b.left,b.top,b.right,b.bottom,"",0xff10a081);out.metrics.put("characters",found.text.length()).put("blocks",found.boxes.size());out.summary="텍스트 "+found.text.length()+"자 · "+found.boxes.size()+"영역";out.detail=found.text;}else{List<PoseGeometry.Point> points=poseModel.pose(input);paint.setColor(0xff10a081);for(PoseGeometry.Point[] edge:PoseGeometry.edges(points))canvas.drawLine(edge[0].x*input.getWidth(),edge[0].y*input.getHeight(),edge[1].x*input.getWidth(),edge[1].y*input.getHeight(),paint);for(PoseGeometry.Point point:PoseGeometry.visible(points))canvas.drawCircle(point.x*input.getWidth(),point.y*input.getHeight(),Math.max(3,input.getWidth()/160f),paint);out.metrics.put("landmarks",points.size()).put("visibleLandmarks",PoseGeometry.visible(points).size()).put("points",SupplementalImageRunner.points(points));out.summary="관측 지점 "+PoseGeometry.visible(points).size()+"개";}out.inferenceMs=SystemClock.elapsedRealtime()-infer;
   }else if("qr".equals(f)){
    out.loadMs=SystemClock.elapsedRealtime()-load;long infer=SystemClock.elapsedRealtime();int w=input.getWidth(),h=input.getHeight();int[] pixels=new int[w*h];input.getPixels(pixels,0,w,0,0,w,h);try{BarcodeHelper.Decoded decoded=BarcodeHelper.decode(pixels,w,h);out.summary=decoded.format;out.detail=decoded.text;out.metrics.put("format",decoded.format).put("characters",decoded.text.length());}catch(com.google.zxing.NotFoundException empty){out.summary="코드 없음";out.metrics.put("characters",0);}out.inferenceMs=SystemClock.elapsedRealtime()-infer;
   }else if(Arrays.asList("faces","access","compare","drive","vis").contains(f)){
    FaceEngine model=new FaceEngine(c,"faces".equals(f)?"face":f,id);engine=model;out.modelSha256=model.modelFingerprint();out.loadMs=SystemClock.elapsedRealtime()-load;long infer=SystemClock.elapsedRealtime();List<Observations.Face> faces=model.analyze(input,!"drive".equals(f),"vis".equals(f)||"faces".equals(f));out.inferenceMs=SystemClock.elapsedRealtime()-infer;check(cancel);int match=0;try(Registry registry=new Registry(c)){for(Observations.Face face:faces){String text="얼굴";if("access".equals(f)&&face.embedding!=null){Registry.Match m=registry.match(face.embedding,Registry.DEFAULT_THRESHOLD);if(m.matched){text=m.name;match++;}}box(canvas,paint,input,face.left,face.top,face.right,face.bottom,text,0xff0068f8);}}out.metrics.put("faces",faces.size()).put("matches",match).put("embeddingDimension","drive".equals(f)?0:128);out.summary="얼굴 "+faces.size()+"명";if("access".equals(f))out.summary+=" · 등록 일치 "+match+"명";if("faces".equals(f)||"drive".equals(f)||"vis".equals(f))out.detail=OneFacePresentation.details(faces);if("faces".equals(f)||"vis".equals(f))out.metrics.put("expressionModelSha256",FaceEngine.EXPRESSION_SHA256).put("ageModelSha256",FaceEngine.AGE_GENDER_SHA256).put("expressionFaces",model.lastExpressionFaces()).put("ageFaces",model.lastAgeGenderFaces());if("compare".equals(f))out.detail="사진의 얼굴 검출·특징 추출 비교입니다. 두 얼굴 대조는 얼굴 비교 화면에서 실행하세요.";if("drive".equals(f))out.detail+="\n단일 사진 관측 · 지속 시간은 영상 또는 실시간 분석에서 확인하세요.";
   }else throw new IllegalArgumentException("사진 분석 기능을 선택하세요");
   check(cancel);out.state="COMPLETED";
  }catch(Exception|LinkageError|OutOfMemoryError error){out.state=cancel.canceled()?"CANCELED":"ERROR";out.errorType=error.getClass().getSimpleName();out.summary=out.state.equals("CANCELED")?"분석 취소":"분석 오류 · 다른 모델로 계속하세요";}
  finally{out.engineCreated=engine!=null;out.engineCloseReturned=engine==null;try{if(engine!=null){engine.close();out.engineCloseReturned=true;}}catch(Exception|LinkageError error){out.state="ERROR";out.errorType=error.getClass().getSimpleName();}out.elapsedMs=SystemClock.elapsedRealtime()-started;}
  return out;
 }
 private static void check(Cancel c)throws InterruptedIOException{if(c.canceled()||Thread.currentThread().isInterrupted())throw new InterruptedIOException("canceled");}
 private static String assetSha(Context c,String asset)throws Exception{try(InputStream in=c.getAssets().open(asset)){return OneOnnx.hash(in);}}
 private static float bilinear(float[][] map,float x,float y){int h=map.length,w=map[0].length;x=Math.max(0,Math.min(w-1,x));y=Math.max(0,Math.min(h-1,y));int a=(int)x,b=(int)y,aa=Math.min(w-1,a+1),bb=Math.min(h-1,b+1);float dx=x-a,dy=y-b;return (map[b][a]*(1-dx)+map[b][aa]*dx)*(1-dy)+(map[bb][a]*(1-dx)+map[bb][aa]*dx)*dy;}
 private static void box(Canvas canvas,Paint p,Bitmap image,float l,float t,float r,float b,String label,int color){p.setColor(color);p.setStyle(Paint.Style.STROKE);canvas.drawRect(l*image.getWidth(),t*image.getHeight(),r*image.getWidth(),b*image.getHeight(),p);if(label!=null&&!label.isEmpty()){p.setStyle(Paint.Style.FILL);p.setTextSize(Math.max(15,image.getWidth()/35f));canvas.drawText(label,l*image.getWidth()+3,Math.max(p.getTextSize(),t*image.getHeight()-4),p);}}
}
